parameters.jsCode:
const headers = $json.headers ?? {};

function header(name) {
  const value =
    headers[name] ??
    headers[name.toLowerCase()] ??
    headers[name.toUpperCase()];

  return typeof value === 'string' ? value.trim() : '';
}

function isIpv4(value) {
  const parts = value.split('.');

  return parts.length === 4 && parts.every((part) => {
    if (!/^\d{1,3}$/.test(part)) return false;

    const number = Number(part);

    return (
      number >= 0 &&
      number <= 255 &&
      String(number) === String(Number(part))
    );
  });
}

function isIpv6(value) {
  let ip = value.toLowerCase();

  if (ip.startsWith('::ffff:') && ip.includes('.')) {
    return isIpv4(ip.slice(7));
  }

  if (!/^[0-9a-f:]+$/.test(ip) || ip.includes(':::')) return false;

  const doubles = (ip.match(/::/g) ?? []).length;

  if (doubles > 1) return false;

  const parts = ip.split(':');
  const groups = parts.filter(Boolean);

  if (
    !groups.every(
      (part) =>
        part.length <= 4 &&
        /^[0-9a-f]+$/.test(part)
    )
  ) {
    return false;
  }

  return ip.includes('::')
    ? groups.length < 8
    : groups.length === 8;
}

const candidate =
  header('cf-connecting-ip') ||
  header('x-real-ip') ||
  header('x-forwarded-for').split(',')[0]?.trim() ||
  '';

const clientIp = candidate.replace(/^\[|\]$/g, '');

const valid =
  isIpv4(clientIp) ||
  isIpv6(clientIp);

const clientIpKey = valid
  ? clientIp.replace(/[^0-9a-zA-Z]/g, '_')
  : null;

return [{
  json: {
    valid,
    clientIp: valid ? clientIp : null,
    clientIpKey,
  },
}];

parameters.responseBody:
={{ (() => {
  const day = $json ?? {};

  const ipKey =
    $('Extract & Validate Client IP').item.json.clientIpKey;

  const ipUsed = Number(
    day.byIp?.[ipKey]?.usedRecipes ?? 0
  );

  const globalUsed = Number(
    day.globalUsedRecipes ?? 0
  );

  const ipLimit = 3;
  const globalLimit = 12;

  const ipRemaining =
    Math.max(0, ipLimit - ipUsed);

  const globalRemaining =
    Math.max(0, globalLimit - globalUsed);

  const allowed =
    ipRemaining >= 3 &&
    globalRemaining >= 3;

  const reason =
    ipRemaining < 3
      ? 'ip_limit_reached'
      : (
          globalRemaining < 3
            ? 'global_limit_reached'
            : null
        );

  return {
    dayKey:
      $now.setZone('Europe/Berlin').toISODate(),

    ipUsedRecipes: ipUsed,
    ipLimitRecipes: ipLimit,
    ipRemainingRecipes: ipRemaining,

    globalUsedRecipes: globalUsed,
    globalLimitRecipes: globalLimit,
    globalRemainingRecipes: globalRemaining,

    generationAllowed: allowed,
    reason,
  };
})() }}

